def rgb(name):
    """A colour as three floats, for cairo."""
    value = COLOR[name]
    return tuple(int(value[i:i + 2], 16) / 255.0 for i in (1, 3, 5))


def css(name, alpha=None):
    """A colour as CSS text; alpha is a percentage from ALPHA."""
    if alpha is None:
        return COLOR[name]
    if alpha not in ALPHA:
        raise ValueError(f"{alpha} is not on the alpha scale {ALPHA}")
    red, green, blue = (round(part * 255) for part in rgb(name))
    return f"rgba({red}, {green}, {blue}, {alpha / 100:.2f})"
